"""Build the small, crawlable studio website. Python 3 + Pillow + reportlab."""
import os, json, shutil, html
from pathlib import Path
from PIL import Image
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, letter

ROOT=Path(__file__).parent
OUT=ROOT/'dist'
ORIGIN=os.environ.get('SITE_URL','https://patricks-little-studio.harfy.chatgpt.site').rstrip('/')
DATA=json.loads((ROOT/'content.json').read_text())
if OUT.exists(): shutil.rmtree(OUT)
(OUT/'assets').mkdir(parents=True)
(OUT/'downloads').mkdir()
for p in (ROOT/'assets').iterdir(): shutil.copy2(p,OUT/'assets'/p.name)
shutil.copy2(ROOT/'style.css',OUT/'assets/style.css')
e=html.escape
brand="Patrick’s Little Studio"
pages=[]
def image(d,large=False):
    s=d['slug']; return f'<img src="/assets/{s}-{"large" if large else "small"}.webp" width="{1200 if large else 480}" height="{1200 if large else 480}" alt="{e(d["alt"])}" loading="{"eager" if large else "lazy"}" decoding="async">'
def cards(items):
    return '<div class="grid">'+''.join(f'<a class="card" href="/coloring-pages/{d["slug"]}/">{image(d)}<span class="card-label">{e(d["name"])} <span aria-hidden="true">↗</span></span><span class="card-note">{e(d["short"])}</span></a>' for d in items)+'</div>'
def page(path,title,desc,body,schema=None,noindex=False):
    url=ORIGIN+path
    base=[{'@context':'https://schema.org','@type':'WebSite','name':brand,'url':ORIGIN+'/'}, {'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':url}]
    if schema:base+=schema
    doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}"><link rel="canonical" href="{e(url)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{e(url)}"><meta property="og:image" content="{ORIGIN}/assets/octopus-mandala-large.webp"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">{json.dumps(base,ensure_ascii=False).replace('<','\\u003c')}</script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><a class="brand" href="/" aria-label="Patrick’s Little Studio home"><img src="/assets/flower.svg" width="44" height="44" alt=""><span>Patrick’s<br><strong>Little Studio</strong></span></a><nav aria-label="Main navigation"><a href="/coloring-pages/">The mandalas</a><a href="/about/">Meet the studio</a></nav></header><main id="main">{body}</main><footer><div class="footer-top"><a class="footer-brand" href="/">Patrick’s Little Studio</a><p>A little paper. A little color. A little time to play.</p></div><div class="footer-links"><a href="/coloring-pages/">All mandalas</a><a href="/about/">About & creative process</a><a href="/terms/">Printing & use</a><a href="/privacy/">Privacy</a></div><small>© 2026 Patrick’s Little Studio · Free for personal and classroom coloring.</small></footer></body></html>'''
    dest=OUT/('404.html' if path=='/404/' else path.lstrip('/')+'index.html')
    dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(doc)
    if not noindex:pages.append(path)

for d in DATA:
    s=d['slug']
    for label,size in [('small',480),('large',1200)]:
        im=Image.open(ROOT/'originals'/f'{s}.png').convert('RGB');im.thumbnail((size,size));im.save(OUT/'assets'/f'{s}-{label}.webp',quality=90)
    for name,size in [('a4',A4),('letter',letter)]:
        c=canvas.Canvas(str(OUT/'downloads'/f'{s}-{name}.pdf'),pagesize=size)
        c.setTitle(d['name']+' - printable mandala');c.setAuthor(brand)
        w,h=size;side=min(w-64,h-120)
        c.setFont('Helvetica',13);c.drawCentredString(w/2,h-42,d['name'])
        c.drawImage(str(ROOT/'originals'/f'{s}.png'),(w-side)/2,(h-side)/2,width=side,height=side)
        c.setFont('Helvetica',9);c.drawCentredString(w/2,32,"Patrick's Little Studio | Personal & classroom use")
        c.showPage();c.save()

page('/',"Free Mandalas for Kids | Patrick’s Little Studio",'Seven easy printable mandalas for kids: friendly animals, a woodland cottage, and sun and moon. Choose a design and download a free A4 or Letter PDF.',f'''<section class="hero"><div><p class="eyebrow">WELCOME TO MY LITTLE STUDIO</p><h1>Big imagination.<br>Little moments<br>of <em>color.</em></h1><p class="intro">Free printable mandalas for kids, filled with friendly faces and simple shapes. Pick a favorite, grab your pencils, and make it yours.</p><a class="button" href="#collection">Find your mandala <span aria-hidden="true">↓</span></a><p class="quiet">Seven designs. Free PDFs. No sign-up.</p></div><div class="hero-art">{image(DATA[0],True)}<span class="scribble">Your colors go here ↗</span></div></section><section id="collection"><div class="section-heading"><div><p class="eyebrow">THE FIRST LITTLE COLLECTION</p><h2>Easy mandalas to print & color</h2></div><p>Simple shapes, roomy spaces,<br>and a character in every circle.</p></div>{cards(DATA)}</section><section class="studio"><img src="/assets/patrick.webp" width="600" height="600" alt="AI-created portrait of Patrick, the fictional studio character, at a drawing desk" loading="lazy"><div><p class="eyebrow">A FACE BEHIND THE CIRCLES</p><h2>Hello from<br>the little studio.</h2><p>Patrick is our fictional studio host: a friendly face for a collection made to get children coloring. The drawings pair playful characters with repeating shapes, leaving plenty of room for small hands and big ideas.</p><a class="text-link" href="/about/">Meet Patrick & explore the creative process ↗</a></div></section><section class="print-guide"><p class="eyebrow">FROM SCREEN TO PAPER</p><h2>Ready in three little steps.</h2><ol><li><strong>Pick a circle.</strong><span>Open any design to see the full drawing.</span></li><li><strong>Print a page.</strong><span>Choose A4 or US Letter, then print at actual size.</span></li><li><strong>Make it yours.</strong><span>Use crayons, pencils, or markers. There is no right palette.</span></li></ol><p>Every design is free for home and classroom coloring. <a href="/terms/">Read the simple use guidelines.</a></p></section>''')
page('/coloring-pages/','Easy Printable Mandalas for Kids | The Collection', 'Browse seven simple mandala coloring pages for kids, with large geometric spaces and free printable A4 and US Letter PDFs.',f'''<section class="page-heading"><p class="eyebrow">SEVEN LITTLE WORLDS</p><h1>Printable mandalas<br>for curious kids.</h1><p class="intro">Animals, a woodland home, and a smiling sky. Each circular design combines a clear central picture with repeating geometric shapes. These easy pages are intended for children who prefer larger coloring spaces.</p></section>{cards(DATA)}<section class="prose"><h2>Which mandala should you choose?</h2><p>Start with the butterfly or bee for broad, simple sections. The cottage offers windows and a little path, while the turtle adds a few smaller shell sections. Choose the drawing that interests your child rather than an exact age label.</p><h2>Printing your free PDF</h2><p>Open a design and choose the paper size that matches your printer. Print in portrait orientation at actual size or 100%. The page includes white margins, so borderless printing is unnecessary. For markers, use suitable paper and protect the table underneath.</p></section>''')
for i,d in enumerate(DATA):
    s=d['slug'];path=f'/coloring-pages/{s}/'
    related=[DATA[x] for x in d['related']]
    breadcrumbs={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'},{'@type':'ListItem','position':2,'name':'Mandalas','item':ORIGIN+'/coloring-pages/'},{'@type':'ListItem','position':3,'name':d['name'],'item':ORIGIN+path}]}
    img_schema={'@context':'https://schema.org','@type':'ImageObject','name':d['name'],'description':d['alt'],'contentUrl':ORIGIN+f'/assets/{s}-large.webp','acquireLicensePage':ORIGIN+'/terms/','license':ORIGIN+'/terms/','creditText':brand,'creator':{'@type':'Organization','name':brand}}
    page(path,d['seo']+' | Patrick’s Little Studio',d['description'],f'''<nav class="crumbs" aria-label="Breadcrumb"><a href="/">Home</a> / <a href="/coloring-pages/">Mandalas</a> / <span>{e(d['name'])}</span></nav><section class="detail"><div class="drawing">{image(d,True)}</div><div class="detail-copy"><p class="eyebrow">A LITTLE CIRCLE TO MAKE YOUR OWN</p><h1>{e(d['seo'])}</h1><p class="intro">{e(d['intro'])}</p><ul class="facts"><li>Black & white line art</li><li>Large spaces for kids</li><li>Free personal & classroom use</li></ul><h2 class="download-title">Print your mandala</h2><div class="downloads"><a class="button" href="/downloads/{s}-a4.pdf" download>Download A4 PDF ↓</a><a class="button secondary" href="/downloads/{s}-letter.pdf" download>Download US Letter PDF ↓</a></div><p class="quiet">One page per PDF · Portrait · Print at 100%<br>Open the downloaded PDF to print.</p></div></section><section class="prose"><h2>Inside this little mandala</h2><p>{e(d['detail'])}</p><h2>A coloring idea to try</h2><p>{e(d['activity'])}</p><h2>Make a little moment of it</h2><p>{e(d['tip'])}</p><p>Use pencils or crayons for the smaller sections. Print on paper suited to your materials, and put a protective sheet underneath if using markers. Downloads are free for home and classroom use; please link to this page when sharing the design online.</p></section><section><div class="section-heading"><h2>Another circle to explore</h2><a class="text-link" href="/coloring-pages/">See all seven mandalas ↗</a></div>{cards(related)}</section>''',[breadcrumbs,img_schema])
page('/about/','About the Studio & Patrick | Patrick’s Little Studio','Meet Patrick, the fictional studio host, and learn how these AI-assisted printable mandalas are developed for children.', '''<section class="studio about"><img src="/assets/patrick.webp" width="600" height="600" alt="AI-generated portrait of Patrick, our fictional studio host"><div><p class="eyebrow">HELLO FROM THE STUDIO</p><h1>A little imagination,<br>on a sheet of paper.</h1><p class="intro">Patrick’s Little Studio is a small collection of playful printable mandalas for kids. Simple shapes and friendly characters are at the heart of every page.</p></div></section><section class="prose"><h2>Who is Patrick?</h2><p>Patrick is a fictional character created for this project, and his portrait was generated with AI. He gives the studio a friendly face; he is not a real teacher or an accredited art professional.</p><h2>How the drawings are made</h2><p>These designs are created with generative AI from individual creative briefs. The briefs specify circular compositions, a clear central motif, black outlines, large coloring spaces, and simpler geometric surroundings. The selected images are checked visually and prepared as printable PDFs in two paper sizes.</p><h2>What makes this collection different?</h2><p>The collection starts with just seven drawings. Each has its own subject and coloring idea, without an overwhelming catalog to scroll through. The artwork stays black and white so the finished palette belongs to the child.</p><h2>For home and classroom</h2><p>Download and print the designs for personal activities or classroom coloring. No account is required. These are creative activities, not assessments or promises of educational or health outcomes.</p><a class="button" href="/coloring-pages/">Explore the seven mandalas ↗</a></section>''')
page('/terms/','Printing & Use Guidelines | Patrick’s Little Studio','Simple guidelines for downloading, printing and sharing the studio’s mandalas.', '''<section class="prose page-heading"><h1>Printing & use</h1><h2>Enjoy the pages</h2><p>You may download and print these designs for personal, family, and classroom coloring, without charge. You may share photographs of your own colored versions.</p><h2>Share the page, not a new download</h2><p>When recommending a design online, link to its page here. Please do not sell the files, upload them as your own collection, or redistribute the uncolored downloads on another website.</p><h2>AI-assisted artwork</h2><p>The designs and Patrick’s portrait were generated with AI. These guidelines describe the studio’s permitted uses; they do not claim exclusive copyright in every AI-generated element.</p><h2>Printer settings</h2><p>Choose the A4 or US Letter version matching your paper. Use portrait orientation and actual size (100%). Your printer and materials determine the final result.</p></section>''',noindex=True)
page('/privacy/','Privacy | Patrick’s Little Studio','Information about the simple, account-free studio website.', '''<section class="prose page-heading"><h1>Privacy</h1><p>This version of the studio has no account system, contact form, advertising scripts, or analytics added by the studio. It does not ask you to submit personal information to download a drawing.</p><h2>Hosting and requests</h2><p>Like other websites, the hosting service may process technical request data, such as IP addresses and browser information, to deliver and secure the website. A private preview may require sign-in handled by the hosting platform.</p><h2>Files and external services</h2><p>PDF downloads are served directly from the website. No externally hosted fonts or social media embeds are used. This information will need updating if additional services are introduced.</p></section>''',noindex=True)
page('/404/','Page Not Found | Patrick’s Little Studio','Find a printable mandala in the studio.', '<section class="page-heading"><p class="eyebrow">A LITTLE WRONG TURN</p><h1>This circle is missing.</h1><p>The page could not be found. Your next coloring page is still waiting.</p><a class="button" href="/coloring-pages/">Explore the mandalas ↗</a></section>',noindex=True)
xml='\n'.join(f'<url><loc>{ORIGIN+p}</loc></url>' for p in pages)
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+xml+'</urlset>')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
(OUT/'_headers').write_text('/downloads/*\n  X-Robots-Tag: noindex\n/assets/*\n  Cache-Control: public, max-age=86400\n/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n')
print(f'Built {len(pages)} indexable pages, 3 noindex pages and 14 PDFs at {ORIGIN}')
